<script lang="ts">let{data,form}=$props();</script>
{#if form?.error}<p class="form-error">{form.error}</p>{/if}{#if form?.saved}<p class="form-success">Rule Hook created.</p>{/if}
<div class="admin-grid two-column-admin admin-workspace-frame">
  <section class="panel stack"><div class="panel-head"><div><h2>Rule Hook Library</h2><p class="muted">Advanced engine locations. Keys are immutable once used.</p></div><span>{data.hooks.length}</span></div><form method="GET" class="inline"><input name="q" placeholder="Search hooks"/><button>Search</button></form><div class="admin-list">{#each data.hooks as hook}<article class="admin-row"><div><strong>{hook.label}</strong><p class="muted">{hook.key} · {hook.valueKind}{hook.isArchived?' · archived':''}</p></div><div class="actions"><span class:good={hook.runtimeSupported} class="save-state">{hook.runtimeSupported?'Calculated':'Stored only'}</span>{#if !hook.isSystem}<form method="POST" action="?/archive"><input type="hidden" name="targetKey" value={hook.key}/><button class="compact-button danger">{hook.isArchived?'Restore':'Archive'}</button></form>{/if}</div></article>{/each}</div></section>
  <section class="panel stack"><h2>Guided Rule Hook Builder</h2><form method="POST" action="?/create" class="stack admin-form"><label>Namespace<select name="namespace"><option value="ability_check">Ability Check</option><option value="saving_throw">Saving Throw</option><option value="attack_roll">Attack Roll</option><option value="damage_roll">Damage Roll</option><option value="damage_taken">Damage Taken</option><option value="movement">Movement</option><option value="spell">Spell</option><option value="resource">Resource</option><option value="custom">Custom</option></select></label><label>Qualifier<input name="qualifier" placeholder="stealth or melee_weapon.dex"/></label><label>Display Name<input name="label" required/></label><div class="mini-grid"><label>Category<select name="category"><option>checks</option><option>saves</option><option>combat</option><option>damage</option><option>spellcasting</option><option>movement</option><option>resources</option><option>custom</option></select></label><label>Value Type<select name="valueKind"><option value="formula">Formula</option><option value="number">Number</option><option value="dice">Dice</option><option value="none">None</option><option value="text">Text</option></select></label></div><label>Description<textarea name="description"></textarea></label><p class="muted">New hooks are stored only until the rules engine explicitly supports them.</p><button>Create Rule Hook</button></form></section>
</div>
